using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using TradeRecon.Application.Audit;
using Xunit;

namespace TradeRecon.Tests;

public class AuditWorkflowTests
{
    [Fact]
    public void ProposeAndDecide_ProduceOrderedHashChain()
    {
        var stateDirectory = CreateStateDirectory();
        try
        {
            var initialize = AuditWorkflow.Initialize(stateDirectory);
            Assert.True((bool?)initialize.GetType().GetProperty("ok")?.GetValue(initialize) == true);

            var propose = AuditWorkflow.Propose(
                stateDirectory,
                "REQ-001",
                "maker-a",
                "2024-06-03",
                "Break is due to ACC001 mismatch.",
                "Evidence: ACC001 settlement amount 12345.67");
            var proposalDoc = JsonDocument.Parse(JsonSerializer.Serialize(propose));
            Assert.Equal("PROPOSED", proposalDoc.RootElement.GetProperty("action").GetString());
            Assert.Equal(1, proposalDoc.RootElement.GetProperty("sequence").GetInt32());
            Assert.DoesNotContain("ACC001", JsonSerializer.Serialize(propose));
            Assert.DoesNotContain("12345.67", JsonSerializer.Serialize(propose));

            var decision = AuditWorkflow.Decide(stateDirectory, "REQ-001", "checker-b", "APPROVED");
            var decisionDoc = JsonDocument.Parse(JsonSerializer.Serialize(decision));
            Assert.Equal("APPROVED", decisionDoc.RootElement.GetProperty("action").GetString());
            Assert.Equal("checker-b", decisionDoc.RootElement.GetProperty("actor").GetString());
            Assert.Equal(2, decisionDoc.RootElement.GetProperty("sequence").GetInt32());

            var exportPath = Path.Combine(stateDirectory, "audit-export.json");
            var export = AuditWorkflow.Export(stateDirectory, "2024-06-03", "2024-06-03", exportPath);
            var exportDoc = JsonDocument.Parse(JsonSerializer.Serialize(export));
            var entries = exportDoc.RootElement.GetProperty("entries");
            Assert.Equal(2, entries.GetArrayLength());

            string? previousHash = null;
            foreach (var entry in entries.EnumerateArray())
            {
                var sequence = entry.GetProperty("sequence").GetInt32();
                Assert.Equal(sequence, sequence);
                var currentHash = entry.GetProperty("hash").GetString();
                if (previousHash is not null)
                {
                    Assert.Equal(previousHash, entry.GetProperty("previousHash").GetString());
                }
                else
                {
                    Assert.Equal(JsonValueKind.Null, entry.GetProperty("previousHash").ValueKind);
                }

                var payload = new
                {
                    sequence = entry.GetProperty("sequence").GetInt32(),
                    timestamp = entry.GetProperty("timestamp").GetString(),
                    requestId = entry.GetProperty("requestId").GetString(),
                    action = entry.GetProperty("action").GetString(),
                    actor = entry.GetProperty("actor").GetString(),
                    proposer = entry.GetProperty("proposer").GetString(),
                    checker = entry.TryGetProperty("checker", out var checkerElement) ? checkerElement.GetString() : null,
                    businessDate = entry.GetProperty("businessDate").GetString(),
                    reason = entry.GetProperty("reason").GetString(),
                    evidence = entry.GetProperty("evidence").GetString(),
                    previousHash = entry.GetProperty("previousHash").ValueKind == JsonValueKind.Null ? null : entry.GetProperty("previousHash").GetString(),
                    version = entry.GetProperty("version").GetInt32()
                };

                var canonical = CanonicalJson(payload);
                using var sha = SHA256.Create();
                var computedHash = Convert.ToHexString(sha.ComputeHash(Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();
                Assert.Equal(computedHash, currentHash);
                previousHash = currentHash;
            }
        }
        finally
        {
            Directory.Delete(stateDirectory, recursive: true);
        }
    }

    [Fact]
    public void SelfApproval_DoesNotPersistFinalDecision()
    {
        var stateDirectory = CreateStateDirectory();
        try
        {
            AuditWorkflow.Propose(stateDirectory, "REQ-002", "maker-a", "2024-06-03", "Need approval.", "Evidence: details");
            var decision = AuditWorkflow.Decide(stateDirectory, "REQ-002", "maker-a", "APPROVED");
            var decisionDoc = JsonDocument.Parse(JsonSerializer.Serialize(decision));
            Assert.False(decisionDoc.RootElement.GetProperty("ok").GetBoolean());

            var export = AuditWorkflow.Export(stateDirectory, "2024-06-03", "2024-06-03", Path.Combine(stateDirectory, "export.json"));
            var exportDoc = JsonDocument.Parse(JsonSerializer.Serialize(export));
            Assert.Equal(1, exportDoc.RootElement.GetProperty("count").GetInt32());
            Assert.Equal("PROPOSED", exportDoc.RootElement.GetProperty("entries")[0].GetProperty("action").GetString());
        }
        finally
        {
            Directory.Delete(stateDirectory, recursive: true);
        }
    }

    [Fact]
    public void RepeatedApproval_IsIdempotent()
    {
        var stateDirectory = CreateStateDirectory();
        try
        {
            AuditWorkflow.Propose(stateDirectory, "REQ-003", "maker-a", "2024-06-03", "Reason", "Evidence");
            var first = AuditWorkflow.Decide(stateDirectory, "REQ-003", "checker-b", "APPROVED");
            var second = AuditWorkflow.Decide(stateDirectory, "REQ-003", "checker-b", "APPROVED");

            var firstDoc = JsonDocument.Parse(JsonSerializer.Serialize(first));
            var secondDoc = JsonDocument.Parse(JsonSerializer.Serialize(second));
            Assert.False(firstDoc.RootElement.GetProperty("idempotent").GetBoolean());
            Assert.True(secondDoc.RootElement.GetProperty("idempotent").GetBoolean());

            var export = AuditWorkflow.Export(stateDirectory, "2024-06-03", "2024-06-03", Path.Combine(stateDirectory, "export.json"));
            var exportDoc = JsonDocument.Parse(JsonSerializer.Serialize(export));
            Assert.Equal(2, exportDoc.RootElement.GetProperty("count").GetInt32());
            var approvedEntries = exportDoc.RootElement.GetProperty("entries").EnumerateArray().Where(item => item.GetProperty("action").GetString() == "APPROVED").ToList();
            Assert.Single(approvedEntries);
        }
        finally
        {
            Directory.Delete(stateDirectory, recursive: true);
        }
    }

    [Fact]
    public void ConflictingDecisions_KeepSingleFinalDecision()
    {
        var stateDirectory = CreateStateDirectory();
        try
        {
            AuditWorkflow.Propose(stateDirectory, "REQ-004", "maker-a", "2024-06-03", "Reason", "Evidence");
            var approve = AuditWorkflow.Decide(stateDirectory, "REQ-004", "checker-b", "APPROVED");
            var reject = AuditWorkflow.Decide(stateDirectory, "REQ-004", "checker-c", "REJECTED");

            var approveDoc = JsonDocument.Parse(JsonSerializer.Serialize(approve));
            var rejectDoc = JsonDocument.Parse(JsonSerializer.Serialize(reject));
            Assert.Equal("APPROVED", approveDoc.RootElement.GetProperty("action").GetString());
            Assert.True(rejectDoc.RootElement.GetProperty("conflict").GetBoolean());

            var export = AuditWorkflow.Export(stateDirectory, "2024-06-03", "2024-06-03", Path.Combine(stateDirectory, "export.json"));
            var exportDoc = JsonDocument.Parse(JsonSerializer.Serialize(export));
            var finalEntries = exportDoc.RootElement.GetProperty("entries").EnumerateArray().Where(item => item.GetProperty("action").GetString() == "APPROVED" || item.GetProperty("action").GetString() == "REJECTED").ToList();
            Assert.Single(finalEntries);
        }
        finally
        {
            Directory.Delete(stateDirectory, recursive: true);
        }
    }

    private static string CreateStateDirectory()
    {
        var directory = Path.Combine(Path.GetTempPath(), "audit-tests-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        return directory;
    }

    private static string CanonicalJson(object value)
    {
        var element = JsonSerializer.SerializeToElement(value);
        return CanonicalizeJsonElement(element);
    }

    private static string CanonicalizeJsonElement(JsonElement element)
    {
        return element.ValueKind switch
        {
            JsonValueKind.Object => "{" + string.Join(",", element.EnumerateObject().OrderBy(pair => pair.Name, StringComparer.Ordinal).Select(pair => JsonSerializer.Serialize(pair.Name) + ":" + CanonicalizeJsonElement(pair.Value))) + "}",
            JsonValueKind.Array => "[" + string.Join(",", element.EnumerateArray().Select(CanonicalizeJsonElement)) + "]",
            JsonValueKind.String => JsonSerializer.Serialize(element.GetString() ?? string.Empty),
            JsonValueKind.Number => element.GetRawText(),
            JsonValueKind.True => "true",
            JsonValueKind.False => "false",
            JsonValueKind.Null => "null",
            _ => "null"
        };
    }
}

